package io.descoped.rawdata.api;

import java.time.Instant;
import java.util.Comparator;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Message ids: UUIDv7 (RFC 9562), laid out as PostgreSQL 18's {@code uuidv7()} lays them out, so an id can be stored
 * in a {@code uuid} column, generated by the database, and read with {@code uuid_extract_timestamp()}.
 * <pre>
 *  48 bits  unix_ts_ms   milliseconds since 1970-01-01T00:00Z
 *   4 bits  version      7
 *  12 bits  rand_a       sub-millisecond fraction (RFC 9562 §6.2, method 3)
 *   2 bits  variant      0b10
 *  62 bits  rand_b       random
 * </pre>
 * Ids sort by time, in the order of {@link #ORDER}, which compares the 16 bytes as unsigned numbers, as PostgreSQL
 * does. {@link UUID#compareTo} compares signed longs and must not be used to order ids.
 */
public final class RawdataIds {

    /**
     * The order of ids in a topic: the 128 bits compared as an unsigned number, the same as PostgreSQL's order of
     * {@code uuid} values.
     */
    public static final Comparator<UUID> ORDER = (a, b) -> {
        int most = Long.compareUnsigned(a.getMostSignificantBits(), b.getMostSignificantBits());
        return most != 0 ? most : Long.compareUnsigned(a.getLeastSignificantBits(), b.getLeastSignificantBits());
    };

    private static final long VERSION_7 = 0x7000L;
    private static final long VARIANT = 0x8000_0000_0000_0000L;
    private static final long RAND_A_MASK = 0x0FFFL;
    private static final long RAND_B_MASK = 0x3FFF_FFFF_FFFF_FFFFL;
    private static final long MAX_TIMESTAMP = 0xFFFF_FFFF_FFFFL;

    private RawdataIds() {
    }

    /**
     * Whether an id is a UUIDv7 with the RFC 9562 variant.
     *
     * @param id the id
     * @return true for a UUIDv7; false for any other UUID or null
     */
    public static boolean isValid(UUID id) {
        return id != null && id.version() == 7 && id.variant() == 2;
    }

    /**
     * Checks that an id is a UUIDv7.
     *
     * @param id the id
     * @return the id
     * @throws NullPointerException     if the id is null
     * @throws IllegalArgumentException if the id is not a UUIDv7
     */
    public static UUID requireValid(UUID id) {
        Objects.requireNonNull(id, "id");
        if (!isValid(id)) {
            throw new IllegalArgumentException("Not a UUIDv7: " + id);
        }
        return id;
    }

    /**
     * Returns the time of an id.
     *
     * @param id a UUIDv7
     * @return the milliseconds since 1970-01-01T00:00Z
     * @throws IllegalArgumentException if the id is not a UUIDv7
     */
    public static long timestamp(UUID id) {
        return requireValid(id).getMostSignificantBits() >>> 16;
    }

    /**
     * Returns the smallest id of a millisecond, which sorts before every id generated in it.
     *
     * @param timestamp the milliseconds since 1970-01-01T00:00Z; clamped to the 48 bits an id holds
     * @return the id
     */
    public static UUID beginningOf(long timestamp) {
        long clamped = Math.max(0, Math.min(MAX_TIMESTAMP, timestamp));
        return new UUID((clamped << 16) | VERSION_7, VARIANT);
    }

    /**
     * Returns the smallest id there is.
     *
     * @return the id of time 0 with no random part
     */
    public static UUID beginningOfTime() {
        return beginningOf(0);
    }

    /**
     * Generates an id for now.
     *
     * @return a new UUIDv7
     */
    public static UUID generate() {
        Instant now = Instant.now();
        long millis = now.toEpochMilli();
        long fraction = ((now.getNano() % 1_000_000L) * 4096L) / 1_000_000L; // 12 bits of the millisecond
        long randB = ThreadLocalRandom.current().nextLong() & RAND_B_MASK;
        if (fraction == 0 && randB == 0) {
            randB = 1; // stay greater than beginningOf(millis)
        }
        return new UUID((millis << 16) | VERSION_7 | fraction, VARIANT | randB);
    }

    /**
     * Generates an id greater than a previous one, for producers: a new id when the clock is ahead of the previous
     * id, otherwise the previous id plus one. So ids stay ordered when several are made in one millisecond and when
     * the clock moves back, as PostgreSQL 18 keeps its own {@code uuidv7()} ordered.
     *
     * @param previous the previous id, typically the greatest in the topic
     * @return a UUIDv7 greater than the previous id
     * @throws IllegalArgumentException if the previous id is not a UUIDv7
     * @throws IllegalStateException    if the previous id is the greatest UUIDv7 there is
     */
    public static UUID next(UUID previous) {
        requireValid(previous);
        UUID generated = generate();
        return ORDER.compare(generated, previous) > 0 ? generated : increment(previous);
    }

    private static UUID increment(UUID id) {
        long timestamp = id.getMostSignificantBits() >>> 16;
        long randA = id.getMostSignificantBits() & RAND_A_MASK;
        long randB = id.getLeastSignificantBits() & RAND_B_MASK;
        if (randB < RAND_B_MASK) {
            randB++;
        } else {
            randB = 0;
            if (randA < RAND_A_MASK) {
                randA++;
            } else {
                randA = 0;
                if (timestamp == MAX_TIMESTAMP) {
                    throw new IllegalStateException("No UUIDv7 is greater than " + id);
                }
                timestamp++;
            }
        }
        return new UUID((timestamp << 16) | VERSION_7 | randA, VARIANT | randB);
    }
}
